import { Component, EventEmitter, Output, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { CategorieService } from '../categorie/categorie.service';
import { ProductService } from '../product/product.service';
import { LoginComponent } from '../login/login.component';

interface Produto {
  id: number;
  name: string;
  price: string;
  description: string;
  imageUrl: string;
  items: string;
  categoriaId: number;
  categoriaName?: string;
  isEnabled: boolean;
  createdAt: string;
  updatedAt: string;
}

interface CategoriaResponse {
  result: { id: number; name: string }[];
  total: number;
  totalPages: number;
}

interface ProdutoResponse {
  result: Produto[];
  total: number;
  currentPage: number;
  totalPages: number;
}

@Component({
  selector: 'app-product',
  templateUrl: './product.component.html',
  styleUrls: ['./product.component.css'],
})
export class ProductComponent implements OnInit {
  @Output() novoProduto = new EventEmitter<any>();
  produtoForm: FormGroup;
  produtosCadastrados: Produto[] = [];
  exibirFormulario: boolean = false;
  categorias: { id: number; name: string }[] = [];
  page: number = 1;
  exibirModalCategoria = false;
  exibirModalConfirmacao: boolean = false;
  nomeCategoria: string = '';
  categoriaForm: FormGroup;

  currentPage = 0;
  totalPages = 1;

  constructor(
    private fb: FormBuilder,
    private productService: ProductService,
    private categorieService: CategorieService
  ) {
    this.produtoForm = this.fb.group({
      name: ['', Validators.required],
      description: ['', Validators.required],
      price: [0, [Validators.required, Validators.min(0.01)]],
      imageUrl: ['', Validators.required],
      categoryId: ['', Validators.required],
      isEnabled: [true],
      items: ['', Validators.required],
    });

    this.categoriaForm = this.fb.group({
      name: ['', [Validators.required, Validators.maxLength(50)]],
    });
  }

  ngOnInit(): void {
    this.carregarCategorias();
    this.carregarProdutos();
  }

  carregarCategorias() {
    this.productService.findAllCategories().subscribe(
      (categorias: CategoriaResponse) => {
        this.categorias = categorias.result;
      },
      (error) => {
        console.error('Erro ao carregar categorias', error);
      }
    );
  }

  adicionarProduto() {
    if (this.produtoForm.valid) {
      this.toggleModalConfirmacao(); // Exibe o modal de confirmação
    }
  }

  confirmarAdicaoProduto() {
    const produtoCriado = { ...this.produtoForm.value };

    this.productService.create(produtoCriado).subscribe(
      (response) => {
        this.produtosCadastrados.push(response);
        this.novoProduto.emit(response);
        this.produtoForm.reset({
          name: '',
          description: '',
          items: '',
          price: 0,
          imageUrl: '',
          categoryId: '',
          isEnabled: true,
        });
        this.exibirFormulario = false;
        this.toggleModalConfirmacao(); // Fecha o modal de confirmação
      },
      (error) => {
        console.error('Erro ao adicionar produto:', error);
        alert(
          `Erro ao adicionar produto: ${error.message || 'Erro desconhecido'}`
        );
      }
    );
  }

  cancelarAdicaoProduto() {
    this.toggleModalConfirmacao(); // Fecha o modal de confirmação sem salvar
  }

  toggleModalConfirmacao() {
    this.exibirModalConfirmacao = !this.exibirModalConfirmacao;
  }

  carregarProdutos(page: number = 0) {
    this.productService.findAll(page).subscribe(
      (produtos: ProdutoResponse) => {
        this.produtosCadastrados = produtos.result.map((produto) => {
          console.log('produtos', this.produtosCadastrados);

          const categoria = this.categorias.find(
            (cat) => cat.id === produto.categoriaId
          );
          return {
            ...produto,
            categoriaName: categoria
              ? categoria.name
              : 'Categoria não encontrada',
          };
        });

        this.currentPage = Number(produtos.currentPage) || 0;
        this.totalPages = produtos.totalPages;
      },
      (error) => {
        console.error('Erro ao carregar produtos', error);
      }
    );
  }


  toggleFormulario() {
    this.exibirFormulario = !this.exibirFormulario;
  }

  abrirModalCadastroCategoria() {
    this.exibirModalCategoria = true;
  }

  fecharModalCadastroCategoria() {
    this.exibirModalCategoria = false;
  }

  salvarCategoria() {
    console.log('chegou aqui', this.categoriaForm.value);
  }

  editarProduto(produto: Produto): void {
    console.log('Editar produto:', produto);
  }

  excluirProduto(produtoId: number): void {
    console.log('Excluir produto com ID:', produtoId);
  }
}
<app-page-body>
  <h2>Produtos Cadastrados</h2>

  <button (click)="toggleFormulario()" class="btn-novo-produto">
    Novo Produto
  </button>

  <!-- Modal de Cadastro de Produto -->
  <div *ngIf="exibirFormulario" class="modal-overlay">
    <div class="modal-content">
      <span class="close-btn" (click)="toggleFormulario()">&times;</span>
      <h2>Cadastrar Produto</h2>
      <form [formGroup]="produtoForm" (ngSubmit)="adicionarProduto()">
        <label for="nome">Nome:</label>
        <input id="nome" formControlName="name" required />

        <label for="itens">Itens:</label>
        <input id="itens" formControlName="items" required />

        <label for="description">Descrição:</label>
        <input id="description" formControlName="description" required />

        <label for="preco">Preço:</label>
        <input
          id="preco"
          formControlName="price"
          type="text"
          mask="separator.2"
          thousandSeparator="."
          decimalMarker=","
          required
        />

        <label for="imagemUrl">URL da Imagem:</label>
        <input id="imagemUrl" formControlName="imageUrl" required />

        <label for="categoria">Categoria:</label>
        <div class="categoria-container">
          <select id="categoria" formControlName="categoryId" required>
            <option value="" disabled>Selecione uma categoria</option>
            <option *ngFor="let categoria of categorias" [value]="categoria.id">
              {{ categoria.name }}
            </option>
          </select>
          <i class="fa fa-plus" (click)="abrirModalCadastroCategoria()"></i>
        </div>

        <label for="ativo">Status:</label>
        <label class="switch">
          <input type="checkbox" formControlName="isEnabled" />
          <span class="slider"></span>
        </label>

        <button type="submit" [disabled]="produtoForm.invalid">
          Cadastrar
        </button>
      </form>
    </div>
  </div>

  <div *ngIf="exibirModalConfirmacao" class="modal-overlay">
    <div class="modal-content">
      <span class="close-btn" (click)="toggleModalConfirmacao()">&times;</span>
      <h2>Confirmação</h2>
      <p>Deseja realmente salvar este produto?</p>
      <button (click)="confirmarAdicaoProduto()">Sim</button>
      <button (click)="cancelarAdicaoProduto()">Não</button>
    </div>
  </div>

  <table>
    <thead>
      <tr>
        <th>Id</th>
        <th>Nome</th>
        <th>Itens</th>
        <th>Descrição</th>
        <th>Preço</th>
        <th>Categoria</th>
        <th>Imagem</th>
        <th>Status</th>
        <th>Ações</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let produto of produtosCadastrados">
        <td>{{ produto.id }}</td>
        <td>{{ produto.name }}</td>
        <td>{{ produto.items }}</td>
        <td>{{ produto.description }}</td>
        <td>R$ {{ produto.price | number : "1.2-2" }}</td>
        <td>{{ produto.categoriaName }}</td>
        <td>
          <img [src]="produto.imageUrl" alt="{{ produto.name }}" width="50" />
        </td>
        <td>{{ produto.isEnabled ? "Ativo" : "Inativo" }}</td>
        <td>
          <button class="btn-icon edit-btn" (click)="editarProduto(produto)">
            <i class="fa fa-pencil"></i>
          </button>
          <button
            class="btn-icon delete-btn"
            (click)="excluirProduto(produto.id)"
          >
            <i class="fa fa-trash"></i>
          </button>
        </td>
      </tr>
    </tbody>
  </table>
  <div class="paginador">
    <button
      (click)="carregarProdutos(currentPage - 1)"
      [disabled]="currentPage === 0"
    >
      Anterior
    </button>
    <span>Página {{ currentPage + 1 }} de {{ totalPages }}</span>
    <button
      (click)="carregarProdutos(currentPage + 1)"
      [disabled]="currentPage >= totalPages - 1"
    >
      Próxima
    </button>
  </div>

  <p *ngIf="produtosCadastrados.length === 0">Nenhum produto cadastrado.</p>

  <!-- Modal de Cadastro de Categoria -->
  <div *ngIf="exibirModalCategoria" class="modal-overlay">
    <div class="modal-content">
      <span class="close-btn" (click)="fecharModalCadastroCategoria()"
        >&times;</span
      >
      <h2>Cadastrar Categoria</h2>
      <form [formGroup]="categoriaForm" (ngSubmit)="salvarCategoria()">
        <label for="nomeCategoria">Nome da Categoria:</label>
        <input id="nomeCategoria" formControlName="name" required />
        <button type="submit" [disabled]="categoriaForm.invalid">
          Salvar Categoria
        </button>
      </form>
    </div>
  </div>
</app-page-body>
